+    common::create_past_the_tool_law(
+        &world,
+        &mut history,
+        "RF1",
+        "EM-0600-4FL",
+        src.clone(),
+        rotary_flow_params(25.0),
+    );
+    let CommandError::Machining(msg) = common::generate_past_the_tool_law(&world, "RF1")
+        .expect_err("a flat tool cannot ride the band")
