+    if let OpParams::RotaryFlow { max_tilt_deg, .. } = &mut no_cone {
+        *max_tilt_deg = 0.0;
+    }
+    assert!(
+        matches!(mk(no_cone), Err(CommandError::Invalid(_))),
+        "a 0 cone allows no lean at all"
